1: /* ═══════════════════════════════════════════════════════════════════════
2:    Home: describe the house in your own words.
3: 
4:    A conversation with the studio's lead architect, in any language. What
5:    she understands lands at once in the brief strip above the conversation
6:    and in the specification sheet, so the plot drawing beside the chat
7:    redraws while the client talks. When the essentials are known, Start
8:    designing runs the studio on exactly that brief. The sheet itself stays
9:    one click away for anyone who prefers fields.
10:    ═══════════════════════════════════════════════════════════════════════ */
11: 
12: // Typed into the empty composer, one after another, to show what can be said.
13: const EXAMPLES = [
14:   "30x40 east-facing plot, G+1, 3 bedrooms and a pooja room",
15:   "A single-storey home for my parents with no stairs",
16:   "40 x 60 site in Bengaluru, courtyard in the middle, strict Vastu",
17:   "Mujhe 30x50 ka plot hai, 2 floor, 4 bedroom chahiye",
18:   "Balcony off the master bedroom upstairs, earthy colours",
19:   "Modern facade with lots of wood, parking for two cars",
20: ];
21: const ROAD = { N: "north", NE: "north-east", E: "east", SE: "south-east", S: "south", SW: "south-west", W: "west", NW: "north-west" };
22: const FLOORS = (n) => (n === 1 ? "Ground only" : `G+${n - 1}`);
23: 
24: const el = (tag, cls, text) => {
25:   const n = document.createElement(tag);
26:   if (cls) n.className = cls;
27:   if (text != null) n.textContent = text;
28:   return n;
29: };
30: 
31: export function mountHome({ host, api: API, setField, start, openManual, uploadFile }) {
32:   const state = { brief: {}, busy: false, history: [], ready: false, request: null };
33:   host.innerHTML = "";
34: 
35:   // The brief so far, as it is understood, with the way to start.
36:   const strip = el("div", "brief-strip");
37:   const facts = el("div", "brief-strip__facts");
38:   const actions = el("div", "brief-strip__act");
39:   const sheet = el("button", "link-btn", "Fill in a form"); sheet.type = "button";
40:   sheet.addEventListener("click", () => openManual("brief"));
41:   const go = el("button", "btn btn--cream btn--start", "Start designing"); go.type = "button"; go.disabled = true;
42:   go.addEventListener("click", () => state.ready && start(state.request, state.brief));
43:   actions.append(sheet, go);
44:   strip.append(facts, actions);
45: 
46:   const log = el("div", "chat__log"); log.setAttribute("role", "log"); log.setAttribute("aria-live", "polite");
47:   const empty = el("div", "chat__empty");
48:   empty.append(el("h2", "chat__hello", "What are we building?"),
49:     el("p", "chat__lede", "Tell me about the plot and the home you have in mind - in any language, as much or as little as you like. I'll ask about whatever matters and leave the rest to sensible defaults."));
50:   empty.append(el("p", "chat__tip", "Already have a plan? Drop the drawing here - DXF, SVG or a photo - and the studio will review it."));
51:   log.append(empty);
52: 
53:   const form = el("form", "composer");
54:   const input = el("textarea", "composer__in"); input.rows = 1; input.maxLength = 4000;
55:   input.placeholder = "";
56:   input.setAttribute("aria-label", "Message Atri");
57:   const sendBtn = el("button", "composer__send"); sendBtn.type = "submit"; sendBtn.disabled = true;
58:   sendBtn.setAttribute("aria-label", "Send");
59:   sendBtn.innerHTML = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 19V5M5 12l7-7 7 7" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg>';
60:   // Attach a drawing: the plan-review route, from inside the conversation.
61:   const attach = el("button", "composer__attach"); attach.type = "button";
62:   attach.setAttribute("aria-label", "Attach a plan to review"); attach.title = "Attach a plan (DXF, SVG, image)";
63:   attach.innerHTML = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M21 11.5l-8.6 8.6a5 5 0 01-7.1-7.1l8.6-8.6a3.3 3.3 0 014.7 4.7l-8.6 8.6a1.7 1.7 0 01-2.4-2.4l7.9-7.9" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>';
64:   const file = el("input"); file.type = "file"; file.hidden = true;
65:   file.accept = ".dxf,.svg,.png,.jpg,.jpeg,.webp,.json,image/*";
66:   attach.addEventListener("click", () => file.click());
67:   file.addEventListener("change", () => file.files[0] && takeFile(file.files[0]));
68:   const ghost = el("span", "composer__ghost");          // the typed-out examples
69:   const field = el("div", "composer__field"); field.append(input, ghost);
70:   form.append(attach, field, sendBtn, file);
71:   host.append(strip, log, form);
72: 
73:   function takeFile(f) {
74:     bubble("you", `📎 ${f.name}`);
75:     bubble("atri", "Reading your drawing - the studio will review it as drawn.");
76:     setTimeout(() => uploadFile(f), 500);
77:   }
78:   // Drop a drawing anywhere on the conversation.
79:   for (const ev of ["dragenter", "dragover"]) host.addEventListener(ev, (e) => { e.preventDefault(); host.classList.add("is-drop"); });
80:   for (const ev of ["dragleave", "drop"]) host.addEventListener(ev, (e) => { e.preventDefault(); if (ev === "drop" || e.target === host) host.classList.remove("is-drop"); });
81:   host.addEventListener("drop", (e) => { const f = e.dataTransfer?.files?.[0]; if (f) takeFile(f); });
82: 
83:   // The placeholder writes an example, erases it quickly and writes the next,
84:   // until the client starts typing.
85:   (function typewriter() {
86:     if (matchMedia("(prefers-reduced-motion: reduce)").matches) { ghost.textContent = EXAMPLES[0]; return; }
87:     let k = 0, i = 0, dir = 1;
88:     const tick = () => {
89:       ghost.hidden = !!input.value || document.activeElement === input && !!input.value;
90:       const ex = EXAMPLES[k % EXAMPLES.length];
91:       if (dir > 0) {
92:         i++;
93:         ghost.textContent = ex.slice(0, i);
94:         if (i >= ex.length) { dir = -1; return setTimeout(tick, 1800); }
95:         return setTimeout(tick, 38 + Math.random() * 40);
96:       }
97:       i -= 2;
98:       ghost.textContent = ex.slice(0, Math.max(0, i));
99:       if (i <= 0) { dir = 1; i = 0; k++; return setTimeout(tick, 350); }
100:       setTimeout(tick, 14);
101:     };
102:     tick();
103:   })();
104: 
105:   const scroll = () => { log.scrollTop = log.scrollHeight; };
106: 
107:   const renderFacts = () => {
108:     const b = state.brief;
109:     const bits = [];
110:     if (b.plot_width) bits.push(b.plot_unit === "ft"
111:       ? `${Math.round(b.plot_width / 0.3048)} × ${Math.round(b.plot_depth / 0.3048)} ft`
112:       : `${(+b.plot_width).toFixed(1)} × ${(+b.plot_depth).toFixed(1)} m`);
113:     if (b.road_direction) bits.push(`Road ${ROAD[b.road_direction] || b.road_direction}`);
114:     if (b.levels) bits.push(FLOORS(b.levels));
115:     if (b.bedrooms) bits.push(`${b.bedrooms} bed`);
116:     for (const a of b.amenities || []) bits.push(a.replace(/^\w/, (c) => c.toUpperCase()));
117:     for (const r of b.rooms || []) {
118:       if (r.level == null && !r.attach_to) continue;
119:       const name = r.type.replace(/_/g, " ");
120:       bits.push(`${name[0].toUpperCase()}${name.slice(1)}${r.level != null ? ` · ${r.level ? `L${r.level}` : "ground"}` : ""}`);
121:     }
122:     if (b.vastu && b.vastu !== "balanced") bits.push(`Vastu ${b.vastu}`);
123:     facts.replaceChildren(...(bits.length ? bits.map((t) => el("span", "fact", t)) : [el("span", "fact fact--empty", "Your brief will appear here as we talk")]));
124:     strip.classList.toggle("is-ready", state.ready);
125:     go.disabled = !state.ready;
126:   };
127:   renderFacts();
128: 
129:   const bubble = (who, text) => {
130:     empty.remove();
131:     const m = el("div", `msg msg--${who}`);
132:     if (who === "atri") m.append(el("span", "msg__av"));
133:     const body = el("div", "msg__body");
134:     body.textContent = text;
135:     m.append(body);
136:     log.append(m);
137:     scroll();
138:     return m;
139:   };
140: 
141:   // What the agent understood also goes into the sheet, so the drawing
142:   // beside the chat follows the conversation.
143:   const apply = (b) => {
144:     if (b.plot_width) setField("plot_width", (+b.plot_width).toFixed(1));
145:     if (b.plot_depth) setField("plot_depth", (+b.plot_depth).toFixed(1));
146:     if (b.road_direction) setField("road_direction", b.road_direction);
147:     if (b.levels) setField("levels", String(Math.min(4, b.levels)));
148:     if (b.bedrooms) setField("bedrooms", String(b.bedrooms));
149:     if (b.bathrooms || b.bedrooms) setField("bathrooms", String(b.bathrooms || b.bedrooms));
150:     if (b.vastu) setField("vastu", b.vastu);
151:     if (b.budget) setField("budget", String(Math.round(b.budget)));
152:     if (b.locality) setField("locality", b.locality);
153:     for (const a of b.amenities || []) setField(`amenity_${a.split(" ")[0]}`, true);
154:   };
155: 
156:   async function send(text, shown = text) {
157:     text = text.trim();
158:     if (state.busy || !text) return;
159:     state.busy = true; sendBtn.disabled = true;
160:     log.querySelectorAll(".quick").forEach((q) => q.remove());
161:     bubble("you", shown);
162:     const typing = el("div", "msg msg--atri msg--typing");
163:     typing.append(el("span", "msg__av"));
164:     const dots = el("div", "typing"); dots.innerHTML = "<i></i><i></i><i></i>";
165:     typing.append(dots); log.append(typing); scroll();
166:     try {
167:       const r = await fetch(`${API}/design/chat`, { method: "POST", headers: { "Content-Type": "application/json" },
168:         body: JSON.stringify({ message: text, brief: state.brief, history: state.history }) });
169:       if (!r.ok) throw new Error(`HTTP ${r.status}`);
170:       const d = await r.json();
171:       typing.remove();
172:       state.brief = d.brief; state.ready = !!d.ready; state.request = d.request;
173:       state.history.push({ role: "user", text }, { role: "assistant", text: d.reply });
174:       apply(d.brief);
175:       renderFacts();
176:       const m = bubble("atri", d.reply);
177:       const opts = (d.questions || []).flatMap((q) => (q.options || []).slice(0, 5));
178:       if (opts.length) {
179:         const row = el("div", "quick");
180:         for (const o of opts) {
181:           const c = el("button", "quick__opt", o); c.type = "button";
182:           c.addEventListener("click", () => send(o));
183:           row.append(c);
184:         }
185:         m.append(row);
186:       }
187:       if (d.ready) {
188:         go.classList.remove("is-pulse"); void go.offsetWidth; go.classList.add("is-pulse");
189:       }
190:       // "Yes, start": the client confirmed, so the studio starts on its own.
191:       if (d.ready && d.start && d.request) setTimeout(() => start(d.request, d.brief), 900);
192:       scroll();
193:     } catch (err) {
194:       typing.remove();
195:       bubble("atri", `I couldn't reach the studio just now (${err.message}). Try again in a moment, or use the form.`);
196:     } finally {
197:       state.busy = false; sendBtn.disabled = !input.value.trim(); input.focus();
198:     }
199:   }
200: 
201:   form.addEventListener("submit", (e) => {
202:     e.preventDefault();
203:     const v = input.value; input.value = ""; input.style.height = ""; sendBtn.disabled = true;
204:     send(v);
205:   });
206:   input.addEventListener("keydown", (e) => { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); form.requestSubmit(); } });
207:   input.addEventListener("input", () => {
208:     input.style.height = "auto"; input.style.height = `${Math.min(180, input.scrollHeight)}px`;
209:     sendBtn.disabled = state.busy || !input.value.trim();
210:   });
211:   return { focus: () => input.focus() };
212: }
